/**
 * Adaptive Swing v2 Phase62 — original native-format CSV / two independently
 * pinned detached Ed25519 *claimed* source-and-receipt signatures.
 *
 * Phase22 strict CSV parser is reused unchanged. The signer and witness keys
 * can both be generated by an operator: crypto validity is NOT exchange/vendor
 * issuer identity, licence entitlement, contemporaneous source clocks, or
 * original native exchange provenance. Never a broker/trading authorization.
 */
import {createHash,createPublicKey,verify as verifySignature} from 'node:crypto';
import {TextDecoder} from 'node:util';
import {auditPhase61OriginalL1CustodyReadiness,
  type Phase61Input,type Phase61IndependentPins,type Phase61Report,
  type Phase61L1CustodyRow}
  from './adaptivePhase61OriginalL1CustodyIntake.js';
import {parseOriginalNativeL1Csv}
  from './adaptiveNativeL1CsvBridge.js';

const SHA=/^[a-f0-9]{64}$/;
const ID=/^[A-Za-z0-9][A-Za-z0-9._:-]{3,119}$/;
const ISO=/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,3})?(?:Z|[+-]\d\d:\d\d)$/;
const DECIMAL=/^(?:0|[1-9]\d*)(?:\.\d{1,8})?$/;
const HEAD=['sourceRecordId','sourceSequence','instrumentKey',
  'eventAt','originalAvailableAt','bid','ask','bidQty','askQty'];
const hash=(v:unknown)=>createHash('sha256')
  .update(JSON.stringify(v)).digest('hex');
const digest=(x:Uint8Array)=>createHash('sha256').update(x).digest('hex');
export const hashPhase62Evidence=hash;
const int=(v:unknown,min:number,max:number):v is number=>
  typeof v==='number'&&Number.isSafeInteger(v)&&v>=min&&v<=max;
const time=(v:unknown):number=>
  typeof v==='string'&&ISO.test(v)?Date.parse(v):NaN;
const decode=(v:unknown,cap:number):Buffer|null=>{
  if(typeof v!=='string'||!v.length||v.length>(cap+2)*4/3+4||
    !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(v))
    return null;
  try{
    const b=Buffer.from(v,'base64');
    return b.length>0&&b.length<=cap&&b.toString('base64')===v?b:null;
  }catch{return null;}
};
export interface Phase62SignedManifest{
  schemaVersion:'ADAPTIVE_PHASE62_NATIVE_CSV_DUAL_RECEIPT_MANIFEST_V1';
  sourceProductCategory:'CLAIMED_NATIVE_HISTORICAL_OPTION_TOP_OF_BOOK';
  originalCsvSha256:string;
  phase61CustodyJsonlSha256:string;
  phase61ContractCatalogSha256:string;
  phase61ExtendedCalendarSha256:string;
  claimedLicenseEvidenceSha256:string;
  originalQuoteCount:number;
  firstOriginalEventAt:string;
  lastOriginalEventAt:string;
  claimedPublisherId:string;
  claimedWitnessId:string;
  publisherClaimedSignedAt:string;
  witnessClaimedReceivedAt:string;
}
export type Phase62SignatureRole='PUBLISHER'|'RECEIPT_WITNESS';
export function phase62SignedMessage(
  role:Phase62SignatureRole,manifest:Phase62SignedManifest
):Buffer{
  // Canonical JSON of full *exact* manifest object and role-specific domain;
  // do not sign a digest without a role separator / source-context binding.
  return Buffer.from('ADAPTIVE_PHASE62_'+role+
    '_NATIVE_CSV_ORIGINAL_ARCHIVE_V1\n'+JSON.stringify(manifest),'utf8');
}
export interface Phase62Input{
  schemaVersion:'ADAPTIVE_PHASE62_NATIVE_CSV_TWO_DETACHED_RECEIPTS_V1';
  source:'OPERATOR_SUPPLIED_NATIVE_CSV_AND_CLAIMED_SIGNERS_UNVERIFIED';
  phase61:Phase61Input;
  phase61Pins:Phase61IndependentPins;
  originalNativeCsvBase64:string;
  signedManifest:Phase62SignedManifest;
  publisherEd25519PublicKeySpkiDerBase64:string;
  witnessEd25519PublicKeySpkiDerBase64:string;
  publisherDetachedSignatureBase64:string;
  witnessDetachedSignatureBase64:string;
}
export interface Phase62IndependentPins{
  schemaVersion:'INDEPENDENT_PHASE62_NATIVE_CSV_RECEIPT_ROLE_PINS_V1';
  expectedPhase61InputSha256:string;
  expectedPhase61PinsSha256:string;
  expectedNativeCsvSha256:string;
  expectedSignedManifestSha256:string;
  expectedPublisherSpkiDerSha256:string;
  expectedWitnessSpkiDerSha256:string;
  expectedPublisherSignatureSha256:string;
  expectedWitnessSignatureSha256:string;
  expectedClaimedPublisherId:string;
  expectedClaimedWitnessId:string;
  expectedNativeCsvQuoteRows:number;
  maximumClaimedPublisherToWitnessLagHours:number;
}
export interface Phase62Report{
  mode:'OFFLINE_NATIVE_CSV_DUAL_DETACHED_RECEIPT_EVIDENCE_COHERENCE';
  status:'INVALID_EVIDENCE'|'INCOMPLETE_EVIDENCE'|
    'DESCRIPTIVE_TWO_CLAIMED_ED25519_SIGNATURES_AND_NATIVE_CSV_CONSISTENT_UNVERIFIED';
  reasonCodes:string[];
  phase61Status:Phase61Report['status']|null;
  syntheticDataset:boolean|null;
  nativeCsvQuoteRows:number;
  rowsMatchingOriginalPhase61CustodyAndPhase50:number;
  distinctSourceInstruments:number;
  publisherAndWitnessKeysDistinct:boolean;
  publisherEd25519SignatureMathematicallyValid:boolean;
  witnessEd25519SignatureMathematicallyValid:boolean;
  claimedPublisherWitnessTimeOrderInternallyConsistent:boolean;
  nativeExchangeOrVendorExportAuthenticated:false;
  independentPublisherIdentityVerified:false;
  independentWitnessIdentityVerified:false;
  independentSourceCaptureClockVerified:false;
  independentlyLicensedHistoricalFnoL1Verified:false;
  officialContractExpiryAndSessionMasterVerified:false;
  untouchedOosStrategyProfitabilityProven:false;
  ivThetaVegaCalibratedWithLicensedData:false;
  originalNativeBrokerNrmlStopAckVerified:false;
  bestContractExpiryRecommendationAuthorized:false;
  executionAuthorized:false;
  productionSafe:false;
  nativeOrderInstruction:null;
  warnings:string[];
}
const WARN=[
  'BOTH_ED25519_KEYS_MAY_HAVE_BEEN_CREATED_BY_THE_SAME_OPERATOR',
  'VALID_DETACHED_SIGNATURES_ARE_NOT_EXTERNAL_ISSUER_OR_VENDOR_ENTITLEMENT_PROOF',
  'PHASE22_NATIVE_FORMAT_CSV_CAN_BE_BACKFILLED_FROM_PHASE61_JSONL',
  'CLAIMED_RECEIPT_TIMESTAMP_IS_SELF_SIGNED_NOT_RFC3161_TRUSTED_CLOCK',
  'A_HISTORICAL_VENDOR_EXPORT_CREATED_LATER_DOES_NOT_PROVE_AT_TIME_AVAILABLE_AT',
  'ORIGINAL_VENDOR_NATIVE_BYTES_AND_LICENSE_NEED_SEPARATE_INDEPENDENT_TRUST',
  'NO_REAL_MARKET_IV_THETA_GAP_PROBABILITIES_OR_STRATEGY_PROFITABILITY_PROVEN',
  'ORIGINAL_NO_ENTRY_DATES_AND_ALL_FOUR_HORIZONS_STAY_IN_PHASE61_OOS_COHORT',
  'NO_GUARANTEED_STOP_FILL_GAP_PROTECTION_NRML_ORDER_GTT_OR_15_15_EXIT'
];
const blank=():Phase62Report=>({
  mode:'OFFLINE_NATIVE_CSV_DUAL_DETACHED_RECEIPT_EVIDENCE_COHERENCE',
  status:'INVALID_EVIDENCE',reasonCodes:[],
  phase61Status:null,syntheticDataset:null,
  nativeCsvQuoteRows:0,rowsMatchingOriginalPhase61CustodyAndPhase50:0,
  distinctSourceInstruments:0,
  publisherAndWitnessKeysDistinct:false,
  publisherEd25519SignatureMathematicallyValid:false,
  witnessEd25519SignatureMathematicallyValid:false,
  claimedPublisherWitnessTimeOrderInternallyConsistent:false,
  nativeExchangeOrVendorExportAuthenticated:false,
  independentPublisherIdentityVerified:false,
  independentWitnessIdentityVerified:false,
  independentSourceCaptureClockVerified:false,
  independentlyLicensedHistoricalFnoL1Verified:false,
  officialContractExpiryAndSessionMasterVerified:false,
  untouchedOosStrategyProfitabilityProven:false,
  ivThetaVegaCalibratedWithLicensedData:false,
  originalNativeBrokerNrmlStopAckVerified:false,
  bestContractExpiryRecommendationAuthorized:false,
  executionAuthorized:false,productionSafe:false,
  nativeOrderInstruction:null,warnings:WARN
});
const reject=(reason:string,status:Phase62Report['status']='INVALID_EVIDENCE',
  partial?:Partial<Phase62Report>):Phase62Report=>({
  ...blank(),...partial,status,reasonCodes:[reason]
});
function checkSignature(
  keyBytes:Buffer,sig:Buffer,role:Phase62SignatureRole,
  manifest:Phase62SignedManifest
):boolean{
  if(sig.length!==64)return false;
  try{
    const key=createPublicKey({key:keyBytes,format:'der',type:'spki'});
    return key.asymmetricKeyType==='ed25519'&&
      Buffer.from(key.export({format:'der',type:'spki'})).equals(keyBytes)&&
      verifySignature(null,phase62SignedMessage(role,manifest),key,sig);
  }catch{return false;}
}
export function auditPhase62NativeCsvDualReceipts(
  input:Phase62Input,pins:Phase62IndependentPins
):Phase62Report{
  if(!input||input.schemaVersion!==
      'ADAPTIVE_PHASE62_NATIVE_CSV_TWO_DETACHED_RECEIPTS_V1'||
    input.source!=='OPERATOR_SUPPLIED_NATIVE_CSV_AND_CLAIMED_SIGNERS_UNVERIFIED'||
    !input.phase61||!input.phase61Pins||
    !pins||pins.schemaVersion!==
      'INDEPENDENT_PHASE62_NATIVE_CSV_RECEIPT_ROLE_PINS_V1'||
    ![pins.expectedPhase61InputSha256,
      pins.expectedPhase61PinsSha256,
      pins.expectedNativeCsvSha256,
      pins.expectedSignedManifestSha256,
      pins.expectedPublisherSpkiDerSha256,
      pins.expectedWitnessSpkiDerSha256,
      pins.expectedPublisherSignatureSha256,
      pins.expectedWitnessSignatureSha256].every(
      x=>typeof x==='string'&&SHA.test(x))||
    pins.expectedPhase61InputSha256!==hash(input.phase61)||
    pins.expectedPhase61PinsSha256!==hash(input.phase61Pins)||
    !int(pins.expectedNativeCsvQuoteRows,1,300000)||
    !int(pins.maximumClaimedPublisherToWitnessLagHours,1,720)||
    !ID.test(pins.expectedClaimedPublisherId??'')||
    !ID.test(pins.expectedClaimedWitnessId??'')||
    pins.expectedClaimedPublisherId===pins.expectedClaimedWitnessId)
    return reject('PHASE62_INDEPENDENT_SOURCE_ROLE_OR_MANIFEST_PINS_INVALID');
  const m=input.signedManifest;
  if(!m||typeof m!=='object'||Object.keys(m).length!==14||
    m.schemaVersion!=='ADAPTIVE_PHASE62_NATIVE_CSV_DUAL_RECEIPT_MANIFEST_V1'||
    m.sourceProductCategory!=='CLAIMED_NATIVE_HISTORICAL_OPTION_TOP_OF_BOOK'||
    ![m.originalCsvSha256,m.phase61CustodyJsonlSha256,
      m.phase61ContractCatalogSha256,m.phase61ExtendedCalendarSha256,
      m.claimedLicenseEvidenceSha256].every(
      x=>typeof x==='string'&&SHA.test(x))||
    m.claimedPublisherId!==pins.expectedClaimedPublisherId||
    m.claimedWitnessId!==pins.expectedClaimedWitnessId||
    m.originalQuoteCount!==pins.expectedNativeCsvQuoteRows||
    hash(m)!==pins.expectedSignedManifestSha256)
    return reject('PHASE62_SIGNED_NATIVE_SOURCE_MANIFEST_MALFORMED_OR_CHANGED');
  const first=time(m.firstOriginalEventAt),last=time(m.lastOriginalEventAt),
    publisherAt=time(m.publisherClaimedSignedAt),
    receiptAt=time(m.witnessClaimedReceivedAt);
  if(![first,last,publisherAt,receiptAt].every(Number.isFinite)||
    first>=last||publisherAt<last||receiptAt<publisherAt||
    receiptAt-publisherAt>
      pins.maximumClaimedPublisherToWitnessLagHours*3600000)
    return reject('PHASE62_SELF_DECLARED_SIGNATURE_RECEIPT_CLOCK_INCOHERENT');
  const csv=decode(input.originalNativeCsvBase64,50_000_000),
    pub=decode(input.publisherEd25519PublicKeySpkiDerBase64,512),
    witness=decode(input.witnessEd25519PublicKeySpkiDerBase64,512),
    pubSig=decode(input.publisherDetachedSignatureBase64,256),
    witSig=decode(input.witnessDetachedSignatureBase64,256);
  if(!csv||!pub||!witness||!pubSig||!witSig)
    return reject('PHASE62_ORIGINAL_VENDOR_CSV_OR_SIGNER_BYTES_MISSING');
  if(digest(csv)!==pins.expectedNativeCsvSha256||
    digest(csv)!==m.originalCsvSha256||
    digest(pub)!==pins.expectedPublisherSpkiDerSha256||
    digest(witness)!==pins.expectedWitnessSpkiDerSha256||
    digest(pubSig)!==pins.expectedPublisherSignatureSha256||
    digest(witSig)!==pins.expectedWitnessSignatureSha256)
    return reject('PHASE62_RAW_CSV_PUBLIC_KEYS_OR_DETACHED_SIGNATURE_PINS_DISAGREE');
  if(pub.equals(witness))
    return reject('PHASE62_CLAIMED_SOURCE_AND_WITNESS_MUST_HAVE_DIFFERENT_KEYS');
  const pubValid=checkSignature(pub,pubSig,'PUBLISHER',m),
    witnessValid=checkSignature(witness,witSig,'RECEIPT_WITNESS',m);
  if(!pubValid||!witnessValid)
    return reject('PHASE62_DETACHED_ORIGINAL_SOURCE_OR_WITNESS_SIGNATURE_INVALID');
  const signed:Partial<Phase62Report>={
    publisherAndWitnessKeysDistinct:true,
    publisherEd25519SignatureMathematicallyValid:true,
    witnessEd25519SignatureMathematicallyValid:true,
    claimedPublisherWitnessTimeOrderInternallyConsistent:true
  };
  const phase61=input.phase61;
  const previousArchives:[
    string,string,string,string
  ]=[
    phase61.originalL1QuoteEnvelopeBase64,
    phase61.originalPointInTimeContractCatalogBase64,
    phase61.originalExtendedSessionCalendarBase64,
    phase61.operatorClaimedLicenseEntitlementEvidenceBase64
  ];
  const archives=previousArchives.map((s,i)=>decode(
    s,i===0||i===1?25_000_000:i===2?10_000_000:1_000_000));
  if(archives.some(x=>x===null))
    return reject('PHASE61_ORIGINAL_SOURCE_ARCHIVES_UNAVAILABLE',
      'INCOMPLETE_EVIDENCE',signed);
  if(digest(archives[0]!)!==m.phase61CustodyJsonlSha256||
    digest(archives[1]!)!==m.phase61ContractCatalogSha256||
    digest(archives[2]!)!==m.phase61ExtendedCalendarSha256||
    digest(archives[3]!)!==m.claimedLicenseEvidenceSha256)
    return reject('PHASE62_SIGNED_MANIFEST_NOT_BOUND_TO_ALL_PHASE61_ARCHIVES',
      'INCOMPLETE_EVIDENCE',signed);
  let old:Phase61Report;
  try{old=auditPhase61OriginalL1CustodyReadiness(
    phase61,input.phase61Pins);}
  catch{return reject('PHASE61_ORIGINAL_OOS_CUSTODY_REAUDIT_EXCEPTION',
    'INCOMPLETE_EVIDENCE',signed);}
  const source:Partial<Phase62Report>={
    ...signed,phase61Status:old.status,syntheticDataset:old.syntheticDataset
  };
  if(old.status!==
      'DESCRIPTIVE_OPERATOR_CUSTODIED_DATA_INTEGRITY_ONLY'||
    old.originalQuoteEnvelopeRows!==pins.expectedNativeCsvQuoteRows||
    old.matchingOriginalPhase50QuoteRows!==pins.expectedNativeCsvQuoteRows)
    return reject('PHASE61_ORIGINAL_SOURCE_OOS_OR_CUSTODY_NOT_COMPLETE',
      'INCOMPLETE_EVIDENCE',source);
  const rows=parseOriginalNativeL1Csv(csv);
  if(!rows||rows.length!==pins.expectedNativeCsvQuoteRows+1||
    rows[0].length!==HEAD.length||
    HEAD.some((h,i)=>rows[0][i]!==h))
    return reject('PHASE62_ORIGINAL_VENDOR_NATIVE_CSV_COLUMNS_OR_DENOMINATOR_INVALID',
      'INCOMPLETE_EVIDENCE',source);
  let custody:Phase61L1CustodyRow[];
  try{
    const body=new TextDecoder('utf8',{fatal:true}).decode(archives[0]!);
    if(!body.endsWith('\n'))throw Error('Unterminated source');
    custody=body.slice(0,-1).split('\n').map(
      s=>JSON.parse(s) as Phase61L1CustodyRow);
  }catch{return reject('PHASE61_ARCHIVED_SOURCE_RECORD_PARSE_FAILED',
    'INCOMPLETE_EVIDENCE',source);}
  if(custody.length!==pins.expectedNativeCsvQuoteRows)
    return reject('PHASE62_NATIVE_CSV_AND_PHASE61_CUSTODY_ROW_COUNTS_DIVERGE',
      'INCOMPLETE_EVIDENCE',source);
  let firstEvent=Infinity,lastEvent=-Infinity,matched=0;
  const instruments=new Set<string>();
  for(let i=1;i<rows.length;i++){
    const v=rows[i],original=custody[i-1];
    if(v.length!==9||!v[1]||!DECIMAL.test(v[1])||
      ![v[5],v[6],v[7],v[8]].every(x=>DECIMAL.test(x))||
      !original||
      v[0]!==original.sourceRecordId||
      Number(v[1])!==original.sourceSequence||
      v[2]!==original.instrumentKey||
      v[3]!==original.observedAt||
      v[4]!==original.availableAt||
      Number(v[5])!==original.bid||
      Number(v[6])!==original.ask||
      Number(v[7])!==original.bidQty||
      Number(v[8])!==original.askQty)
      return reject('PHASE62_NATIVE_VENDOR_CSV_ROW_DIFFERS_FROM_ORIGINAL_OOS_L1',
        'INCOMPLETE_EVIDENCE',{...source,
          nativeCsvQuoteRows:rows.length-1,
          rowsMatchingOriginalPhase61CustodyAndPhase50:matched});
    const event=time(v[3]);
    if(!Number.isFinite(event))
      return reject('PHASE62_NATIVE_CSV_ORIGINAL_EVENT_TIME_INVALID',
        'INCOMPLETE_EVIDENCE',source);
    firstEvent=Math.min(firstEvent,event);
    lastEvent=Math.max(lastEvent,event);
    instruments.add(v[2]);matched++;
  }
  if(firstEvent!==first||lastEvent!==last)
    return reject('PHASE62_SIGNED_MANIFEST_EVENT_RANGE_NOT_ORIGINAL_CSV',
      'INCOMPLETE_EVIDENCE',source);
  return {...blank(),...source,
    status:'DESCRIPTIVE_TWO_CLAIMED_ED25519_SIGNATURES_AND_NATIVE_CSV_CONSISTENT_UNVERIFIED',
    reasonCodes:[
      'TWO_DETACHED_SIGNATURES_MATHEMATICALLY_VALID_ISSUER_IDENTITIES_UNVERIFIED',
      'NATIVE_CSV_EQUIVALENT_TO_OPERATOR_CUSTODY_NOT_INDEPENDENT_MARKET_DATA_PROOF'
    ],
    nativeCsvQuoteRows:rows.length-1,
    rowsMatchingOriginalPhase61CustodyAndPhase50:matched,
    distinctSourceInstruments:instruments.size
  };
}
